const rows = $input.all().map(i => i.json);
const first = rows[0] || {};
return [{ json: {
  success: true, stage: 'SF6',
  picked: 0, fb_found: 0, emails_found: 0, size_found: 0, provider_pending: 0, tavily_credits: 0,
